def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Return True if any two distinct elements in ``numbers`` differ by less than
    ``threshold``. Raises a :class:`TypeError` if the inputs are not of the
    expected types.
    """
    # Validate that numbers is an iterable of real numbers
    if not isinstance(numbers, (list, tuple)):
        raise TypeError(f"numbers must be a list or tuple, got {type(numbers)!r}")

    if not isinstance(threshold, (int, float)):
        raise TypeError(f"threshold must be a real number, got {type(threshold)!r}")

    # Early out: no pair exists if fewer than two elements
    if len(numbers) < 2:
        return False

    # Any non‑numeric value will cause a TypeError
    for i, val in enumerate(numbers):
        if not isinstance(val, (int, float)):
            raise TypeError(f"numbers[{i}] is not a real number: {val!r}")

    # A non‑positive threshold can never be satisfied by distinct values
    if threshold <= 0:
        # If threshold == 0 we could check for exact duplicates,
        # but the problem definition asks for "closer than", so we return False.
        return False

    # Sort the numbers and check only adjacent pairs
    sorted_nums = sorted(numbers)

    for i in range(len(sorted_nums) - 1):
        try:
            diff = abs(sorted_nums[i + 1] - sorted_nums[i])
        except Exception:
            # In case numbers contain values that do not support subtraction
            continue
        if diff < threshold:
            return True

    return False

