def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs of positive integers (P, Q) such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.

    A pair (P, Q) exists iff x0 divides y0. Let m = y0 // x0.
    Then P = x0 * a and Q = x0 * b where a and b are positive integers,
    gcd(a, b) == 1 and a * b == m. The function counts all such ordered pairs.
    """
    # Validate input: gcd cannot exceed lcm and both must be positive
    if x0 <= 0 or y0 <= 0 or x0 > y0:
        return 0

    # Check divisibility
    if y0 % x0 != 0:
        return 0

    m = y0 // x0

    # Euclidean algorithm for gcd
    def _gcd(u: int, v: int) -> int:
        while v:
            u, v = v, u % v
        return abs(u)

    count = 0
    limit = int(m**0.5)
    for a in range(1, limit + 1):
        if m % a == 0:
            b = m // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs a binary tree from its inorder and postorder traversals
    and returns the preorder traversal as a string.
    """
    if not inorder and not postorder:
        return ''
    if len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder lengths must match.")

    # Build a mapping from node value to its index in inorder for O(1) access
    index_map = {}
    for idx, ch in enumerate(inorder):
        if ch in index_map:
            raise ValueError(f"Duplicate node value detected: {ch}")
        index_map[ch] = idx

    def build_pre(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        """
        Recursive helper that returns the preorder string for the subtree defined
        by inorder[in_start:in_end] and postorder[post_start:post_end].
        """
        if in_start >= in_end or post_start >= post_end:
            return ''

        root = postorder[post_end - 1]
        if root not in index_map:
            raise ValueError(f"Node {root} not found in inorder traversal.")

        root_index = index_map[root]
        if root_index < in_start or root_index >= in_end:
            raise ValueError(f"Invalid tree structure: root {root} at wrong inorder position.")

        left_size = root_index - in_start

        left_pre = build_pre(in_start, root_index, post_start, post_start + left_size)
        right_pre = build_pre(root_index + 1, in_end, post_start + left_size, post_end - 1)
        return root + left_pre + right_pre

    return build_pre(0, len(inorder), 0, len(postorder))

