    scenario = scenario.upper()
    liar_set = {name.upper() for name in liar_count}
    days_set = {day.upper() for day in days_of_week}

    # Helper to determine if a statement is about a day of week
    def contains_day_of_week(stmt: str) -> bool:
        words = [w.strip('.,!?').upper() for w in stmt.split()]
        return any(word in days_set for word in words)

    # Helper to evaluate the truth value of a statement
    def evaluate_truth(speaker: str, statement: str) -> bool:
        stmt_lower = statement.lower()
        # Determine if statement is negative
        negative = "not guilty" in stmt_lower

        # Determine target of the statement
        target = None
        if "i am" in stmt_lower:
            target = speaker.upper()
        else:
            # Attempt to find a pattern "NAME is ... guilty"
            words = stmt_lower.replace(".", "").replace(",", "").replace("?", "").split()
            if "is" in words:
                idx = words.index("is")
                if idx > 0:
                    target = words[idx - 1].upper()
            # Fallback to speaker if unable to parse
            if target is None:
                target = speaker.upper()

        # If target is ambiguous or not a name, consider statement unparseable -> default to False
        if not target:
            return False

        # Determine truth: whether the scenario matches the target's guilt status
        if negative:
            return scenario != target
        else:
            return scenario == target

    for speaker, stmt_list in statements.items():
        speaker_upper = speaker.upper()
        for stmt in stmt_list:
            # Skip statements about days of the week
            if contains_day_of_week(stmt):
                continue
            try:
                truth_value = evaluate_truth(speaker_upper, stmt)
            except Exception:
                # If evaluation fails, treat the statement as unverifiable and thus inconsistent
                return False

            is_liar = speaker_upper in liar_set
            if is_liar:
                if truth_value:  # liar said something true
                    return False
            else:
                if not truth_value:  # truth teller said something false
                    return False

    return True

