        # "I am guilty" / "I am not guilty"
        if stmt_clean == "i am guilty":
            return speaker == scenario
        if stmt_clean == "i am not guilty":
            return speaker != scenario

        parts = stmt_clean.split()
        if len(parts) >= 3 and parts[1] == "is":
            person = parts[0]
            if parts[2] == "guilty":
                return person.upper() == scenario.upper()
            if parts[2] == "not" and len(parts) >= 4 and parts[3] == "guilty":
                return person.upper() != scenario.upper()
        # If statement doesn't match known patterns, assume its truth is irrelevant to consistency
        return True

    # Iterate over all participants
    for speaker, stmts in statements.items():
        # Ensure speaker is string and statement list is iterable
        if not isinstance(speaker, str) or not isinstance(stmts, list):
            raise TypeError("Each key in statements must be a string and each value a list.")
        is_liar = speaker in liar_count
        for stmt in stmts:
            if not isinstance(stmt, str):
                raise TypeError("Each statement must be a string.")
            truth = truth_value(speaker, stmt)
            # Skip day-of-week statements
            if truth is None:
                continue
            # Verify consistency
            if is_liar:
                # liar's statement must be false
                if truth:
                    return False
            else:
                # non-liar's statement must be true
                if not truth:
                    return False
    return True

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    """
    Return the maximum total value of herbs that can be picked within time limit T.
    Implements a 0/1 knapsack with capacity T.
    """
    # Validate inputs
    if T is None or T < 0 or not herbs:
        return 0

    # Only consider relevant herbs
    items = [(time, value) for time, value in herbs if time <= T and time >= 0]
    if not items:
        return 0

    # 1‑D DP: dp[time] = best value with capacity time
    dp = [0] * (T + 1)
    for time, value in items:
        # iterate backwards to avoid reuse
        for cap in range(T, time - 1, -1):
            new_val = dp[cap - time] + value
            if new_val > dp[cap]:
                dp[cap] = new_val

    return dp[T]  # best value with capacity T (may leave unused capacity)

